import{z as A,x as d,o as r,c as p,q as t,j as l,D as e,d as i,s as o,S as E,b as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"后缀数组","description":"","frontmatter":{"title":"后缀数组","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/suffix-array.md","filePath":"cs/suffix-array.md","lastUpdated":1791063341000}'),B={name:"cs/suffix-array.md"};function f(S,a,k,m,u,h){const s=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=t('<h1 id="后缀数组" tabindex="-1">后缀数组 <a class="header-anchor" href="#后缀数组" aria-label="Permalink to &quot;后缀数组&quot;">​</a></h1><div class="epigraph"><p>把文本每一个后缀的起点按字典序排好，模式查找就变成在这张起点表上二分。</p><footer>—— 据 Manber and Myers, Suffix Arrays: A New Method for On-Line String Searches, SIAM J. Comput. 1993；Kärkkäinen and Sanders, Simple Linear Work Suffix Array Construction, ICALP 2003 整理</footer></div><p><a href="/cs/space-filling-curve">上一课</a> 把网格线性化。字符串要的是「所有后缀谁更小」。<a href="/cs/kmp">KMP</a> 只预处理模式；文本多次查询或子串统计需要文本侧索引。<a href="/cs/trie">Trie</a> 可挂全部后缀但空间差。本课不写 Hilbert。缺口是后缀数组 \\(SA[i]\\) = 第 \\(i\\) 小后缀的起点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>文本 \\(T[0..n)\\)（常加哨兵）。\\(n\\) 个后缀，比较两后缀最坏 \\(\\Theta(n)\\)，朴素排序 \\(\\Theta(n^2\\log n)\\)。后缀数组存排列，空间 \\(\\Theta(n)\\) 整数，远小于后缀树节点。查找 \\(P\\)：在 \\(SA\\) 上二分，每次用 \\(T[SA[\\cdot]..]\\) 与 \\(P\\) 比较，时间 \\(O(|P|\\log n)\\)。缺口是<strong>用排列代替显式树</strong>，以及后课 LCP 把比较加速。</p><p><span class="marginnote">初学者容易以为 SA 存的是后缀字符串本身——\\(n\\) 个后缀合计 \\(n(n+1)/2\\) 个字符，早就爆了。实际只存 \\(n\\) 个起点下标，\\(\\Theta(n)\\) 个整数；字符串本体始终只有原文一份，要读时拿下标回去取。</span></p><p><span class="marginnote">Manber–Myers 倍增 \\(O(n\\log n)\\)。DC3/skew（Kärkkäinen–Sanders）线性时间。本课钉语义与二分查找；构造选倍增即可讲清。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>倍增：先按首字符秩，再按 \\((rank[i],rank[i+2^k])\\) 当对排序，k 增加。名次相同则后缀相等前缀更长。实现用整数排序。不要把后缀树 Ukkonen 提前当必须。</p><p><span class="marginnote">术语翻译：哨兵就是在文本末尾补一个比所有字符都小的终结符（如 <code>$</code>）。它让长短后缀的比较总能分出胜负——短后缀先「用完」字符时，哨兵替它认输，不必为「一个前缀是另一个的前缀」写特判。</span></p>',10)),(r(),l(E,null,{default:e(()=>[o(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%96%87%E6%9C%AC%20T%22%5D%20--%3E%20SUF%5B%22n%20%E4%B8%AA%E5%90%8E%E7%BC%80%22%5D%0A%20%20SUF%20--%3E%20SA%5B%22SA%3A%20%E5%AD%97%E5%85%B8%E5%BA%8F%E4%B8%8B%E7%9A%84%E8%B5%B7%E7%82%B9%22%5D%0A%20%20P%5B%22%E6%A8%A1%E5%BC%8F%20P%22%5D%20--%3E%20BIN%5B%22%E5%9C%A8%20SA%20%E4%B8%8A%E4%BA%8C%E5%88%86%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"与哈希：期望匹配可以 Karp–Rabin，后课再收；后缀数组确定性、支持所有子串的序结构。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[i("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"\\(SA\\) 上相邻后缀可能公共前缀很长，朴素二分反复重比——这正是下一课 LCP 与 Kasai 的缺口。逆数组 \\(ISA[SA[i]]=i\\) 把位置映回秩，构造与 LCP 都要用。",-1)),a[6]||(a[6]=n("p",null,"倍增构造为什么 \\(\\log n\\) 轮就能收敛，看每一轮各做了什么。",-1)),(r(),l(E,null,{default:e(()=>[o(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20R0%5B%22k%3D0%EF%BC%9A%E6%8C%89%E5%8D%95%E4%B8%AA%E5%AD%97%E7%AC%A6%E6%8E%92%E5%90%8D%22%5D%20--%3E%20D%5B%22%E6%AF%8F%E8%BD%AE%E7%94%A8%E4%BA%8C%E5%85%83%E7%BB%84%E6%8E%92%E5%BA%8F%22%5D%0A%20%20D%20--%3E%20PAIR%5B%22(rank%5Bi%5D%2C%20rank%5Bi%2B2%5E(k-1)%5D)%22%5D%0A%20%20PAIR%20--%3E%20NR%5B%22%E6%8E%92%E5%BA%8F%E5%BE%97%E6%96%B0%E4%B8%80%E8%BD%AE%20rank%22%5D%0A%20%20NR%20--%3E%20Q%7B%222%5Ek%20%E8%A6%86%E7%9B%96%E5%85%A8%E4%B8%B2%E4%BA%86%E5%90%97%22%7D%0A%20%20Q%20--%20%22%E5%90%A6%22%20--%3E%20D%0A%20%20Q%20--%20%22%E6%98%AF%22%20--%3E%20OUT%5B%22rank%20%E5%8D%B3%20SA%EF%BC%8C%E5%85%B1%20log%20n%20%E8%BD%AE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p><span class="marginnote">数字实例：\\(n=8\\) 的文本只需 \\(k=0,1,2\\) 共 3 轮——第 1 轮比较前 2 个字符、第 2 轮前 4 个、第 3 轮前 8 个。每轮排序 \\(O(n\\log n)\\)，总复杂度 \\(O(n\\log^2 n)\\)，换基数排序可到 \\(O(n\\log n)\\)。</span></p><p>本课不把 BWT 全文写完，只承认 BWT 是 \\(SA\\) 的邻近字符排列。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不要求实现 DC3。动态插入字符使 \\(SA\\) 全失效，属动态后缀结构，主干不提前。LCP 数组是下一课必做预处理。</p><p>后课默认：静态文本子串查找可用 \\(SA\\) 二分。相邻后缀的公共前缀用 LCP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>后缀数组：后缀的字典序排列，\\(\\Theta(n)\\) 空间。</li><li>模式查找：\\(O(|P|\\log n)\\) 二分。</li><li>相邻 LCP 下一课线性算。</li><li>出处：Manber and Myers, 1993；Kärkkäinen and Sanders, ICALP 2003。</li></ul>',7))])}const c=A(B,[["render",f]]);export{C as __pageData,c as default};
